<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\HasMany;use Illuminate\Support\Str;
class BackupDestination extends Model{protected $fillable=['tenant_id','uuid','name','provider','endpoint','bucket','region','access_key','secret_key','active','last_verified_at'];protected static function booted():void{static::creating(fn($m)=>$m->uuid??=(string)Str::uuid());}protected function casts():array{return['access_key'=>'encrypted','secret_key'=>'encrypted','active'=>'boolean','last_verified_at'=>'datetime'];}public function getRouteKeyName():string{return'uuid';}public function backups():HasMany{return $this->hasMany(Backup::class);}public function schedules():HasMany{return $this->hasMany(BackupSchedule::class);}public function providerLabel():string{return match($this->provider){'local'=>'Local storage','s3'=>'Amazon S3','r2'=>'Cloudflare R2','b2'=>'Backblaze B2','spaces'=>'DigitalOcean Spaces','custom_s3'=>'Custom S3',default=>strtoupper($this->provider)};}public function usedBytes():int{return (int) $this->backups()->sum('size_bytes');}public function usedLabel():string{$bytes=$this->usedBytes();return $bytes>=1073741824?number_format($bytes/1073741824,1).' GB':number_format($bytes/1048576,1).' MB';}public function isReady():bool{return $this->active&&($this->provider==='local'||filled($this->last_verified_at));}}
